  "implementation": "import json

def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    n = len(nodes)
    if n == 0:
        raise ValueError('No nodes')

    # Build edges: mutual reachability distance for each given pair
    edges = []
    for u, v, d in distances:
        # canonicalize undirected endpoints (sort by string order)
        node1, node2 = (u, v) if u <= v else (v, u)
        mutual_reach = max(core_distance[u], core_distance[v], d)
        edges.append((mutual_reach, node1, node2))

    # Sort by weight, then first endpoint, then second endpoint
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find (Disjoint Set Union) with path compression and union by rank
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError('Disconnected graph: cannot form spanning tree')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }
